struct Dinh{
int name;
int g; // độ dài đường đi từ đỉnh S đến chính nó
int f; // ước lượng đường đi từ S đến G qua nó
int prev; // đỉnh trước nó
}
int DT[50][50];
int n;
int h[50];
Dinh Open[50];
int nO = 0;
Dinh Close[50];
int nC = 0;
void DocFile (int &n, int DT[][50], int h[])
{
FILE *f = fopen(“…/….txt”, “r”);
fscanf(f, “%d”,&n);
for (int i = 0; i < n; i++)
for (int j = 0; j < n; j++ )
fscanf(f, “%d”,&DT[i][j]);
for (i = 0; i<n; i++)
fscanf(f, “%d”,&h[i]);
fclose(f);
}
void ThemDinh(Dinh N, Dinh Set[ ], int &nS) // Them đỉnh vào tập hợp Set
{
Set[nS] = N;
nS ++;
}
void XoaDinh (int vt, Dinh Open[], int &nO) // Xoa đỉnh trong Open tai vị trí vt
{
for (int i = vt; i < nO – 1; i++)
Open[i] = Open[i+1];
nO--;
}
int NhoNhat (Dinh Open[ ], int nO) // trả về vị trí trong Open có f nhỏ nhất
{
int min = Open[0].f;
int vt = 0;
for (int i= 0; i < nO; i++)
if (min > Open[i].f)
{
min = Open[i].f;
vt = i;
}
return vt;
}
int Member(int node, Dinh Set[], int nS) // kiểm tra đỉnh node có là phần tử của tập Set
// Nếu có thì return về vị trí trong tập Set, Không thì return -1
{
for (int i = 0; i < nS; i++)
if (Set[i].name = = node)
return i;
return -1;
}
Void AStart (int S, int G)
{
Dinh N;
N.name = S;
N.g = 0;
N.f = h[S];
N.prev = 0;
ThemDinh(N, Open, nO);
while (nO != 0)
{
int vt = NhoNhat(Open, nO);
Dinh N = Open[vt];
if (N.name = = G)
ThemDinh(N, Close, nC);
else
{
ThemDinh(N, Close, nC);
for (node = 1; node < n; node++)
{
int belong = Member(node, Close, nC);
if (belong = -1 && DT[N.name][node] > 0)
{
int k = Member(node, Open, nO);
if (k >= 0)
{
Dinh Q;
Q = Open[k];
if (N.g + DT[N.name][Q.name] < Q.g)
{
Open[k].g= N.g + DT[N.name][Q.name];
Open[k].f = Open[k].g + h[N.name];
Open[k].prev= N.name;
}
}
else
{
Dinh Q;
Q.name = node;
Q.g = N.g + DT[N.name][Q.name];
Q.f = Q.g + h[Q.name];
Q.prev = N.name;
ThemDinh(Q, Open, nO);
}
}
}
XoaDinh(vt, Open, nO);
}
}
}
void main()
{
DocFile(DT, n);
int S, G; // S: đỉnh bắt đầu, G: đỉnh kết thúc
printf(“Nhập đỉnh bắt đầu: ”);
scanf(“%d”, &S);
printf(“Nhập đỉnh kết thúc: ”);
scanf(“%d”, &G);
AStart(S, G);
int vtG = Member(G, Close, nC);
if (vtG >= 0)
{
printf(“Độ dài đường đi từ %d đến %d là: %d \n”, S, G, Close[vtG].g);
printf(“Đường đi là: %d”, G);
int k = vtG;
while (Close[k].prev != S)
{
printf(“ %d“, Close[k].prev);
k = Member(Close[k].prev, Close, nC);
}
printf(“ %d“, S);
}
else // vtG < 0
printf(“không có đường đi từ %d đến %d”, S, G)
}

int DT[50][50];
int n;
int Open[50];
int nO = 0;
int Close[50];
int nC = 0;
void DocFile (int DT[][], int &n)
{
FILE *f = fopen(“…\DothiSearch.txt”, “r”);
fscanf(f, “%d”,&n);
for (int i = 0; i < n; i++)
for (int j = 0; j < n; j++ )
fscanf(f, “%d”,&DT[i][j]);
fclose(f);
}
void AddMember(int x, int L[], int &nL) // Push
{
for (int i = nL; i>= 1; i--)
L[i] = L[i-1];
L[0] = x;
nL++;
}
void AddMember(int x, int L[], int &nL) // EnQueue For BFS
{
L[nL] = x;
nL++;
}
int Select(int Open[], int &nO) //Pop
{
int x = Open[0];
for (int i = 0; i<nO-1; i++)
Open[i] = Open[i +1];
nO--;
retrun x;
}
int Search(int x, int L[], int nL) // Trả về 1 nếu x thuộc L, trả về 0 nếu x không thuộc L
{
for (int i = 0; i < nL; i++)
if (L[i] ==x)
return 1;
return 0;
}
void DFS(int S)
{
AddMember(S, Open, nO);
while (nO != 0)
{
int k = Select(Open, nO);
if (Search(k, Close, nC) == 0)
{
Travel(k); // printf(“%d ”, k);
AddMember(k, Close, nC);
for(int i = 0; i<n; i ++)
if (DT[k][i] > 0)
if (Search(i, Close, nC) == 0)
AddMember(i, Open, nO);
}
}
}
void main()
{
DocFile(DT, n);
int S;
printf(“Nhập đỉnh bắt đầu: ”);
scanf(“%d”, &S);
DFS(S);
}

